import { useEffect, useState, useCallback } from "react";

export default function AdminOrders() {
  const [orders, setOrders] = useState([]);
  const [updatingId, setUpdatingId] = useState(null);

  const fetchOrders = useCallback(async () => {
    try {
      const res = await fetch("http://127.0.0.1:8000/orders/");
      const data = await res.json();
      setOrders(data);
    } catch (err) {
      console.error("Failed to fetch orders");
    }
  }, []);

  useEffect(() => {
    fetchOrders();

    const interval = setInterval(() => {
      // Do not overwrite while updating a status
      if (!updatingId) fetchOrders();
    }, 2000);

    return () => clearInterval(interval);
  }, [fetchOrders, updatingId]);

  const updateStatus = async (order_id, status) => {
    try {
      setUpdatingId(order_id);

      await fetch(`http://127.0.0.1:8000/orders/${order_id}/status/`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ status }),
      });

      await fetchOrders();
    } catch (err) {
      console.error("Failed to update status");
    } finally {
      setUpdatingId(null);
    }
  };

  return (
    <div>
      <h3>Live Orders</h3>

      {orders.map((o) => (
        <div key={o.order_id} style={{ borderBottom: "1px solid #ccc", padding: 10 }}>
          <h4>Order #{o.order_id}</h4>
          <p>User: {o.user}</p>
          <p>Total: ₹{o.total}</p>

          <select
            value={o.status}
            disabled={updatingId === o.order_id}
            onChange={(e) => updateStatus(o.order_id, e.target.value)}
          >
            <option value="Pending">Pending</option>
            <option value="Ready">Ready</option>
            <option value="Completed">Completed</option>
          </select>
        </div>
      ))}
    </div>
  );
}
